/// Find captured items. Every field is optional; with none of them the newest items are
/// returned. `text` matches every word given, as a whole word or the start of one. `from`
/// and `to` are ISO 8601 with an offset, or "YYYY-MM-DD HH:MM" in the Mac's time zone.
/// `apps` names at most 5 applications, by name (case ignored) or bundle identifier.
/// `threadId` keeps only items linked to that thread. `limit` is 1 to 20 for an agent and 1
/// to 200 for the interface; absent means 10. `cursor` is the `nextCursor` of the previous
/// page.
// MARK: - TPCapturedSearchInput
struct TPCapturedSearchInput: Codable, Equatable, Sendable {
    let apps: [String]?
    let cursor: String?
    let from: String?
    let kinds: [TPCapturedKind]?
    let limit: Int?
    let text: String?
    let threadID: String?
    let to: String?

    enum CodingKeys: String, CodingKey {
        case apps = "apps"
        case cursor = "cursor"
        case from = "from"
        case kinds = "kinds"
        case limit = "limit"
        case text = "text"
        case threadID = "threadId"
        case to = "to"
    }
}

/// The matching items, newest first. `nextCursor` is the cursor of the next page, or null
/// when there is none. `truncated` says the result was cut to fit the caller's size limit. A
/// hit carries no picture: follow it with `captured_get`.
// MARK: - TPCapturedSearchOutput
struct TPCapturedSearchOutput: Codable, Equatable, Sendable {
    let hits: [TPCapturedHit]
    let nextCursor: String?
    let notice: TPCapturedNotice
    let ok: Bool
    let truncated: Bool

    enum CodingKeys: String, CodingKey {
        case hits = "hits"
        case nextCursor = "nextCursor"
        case notice = "notice"
        case ok = "ok"
        case truncated = "truncated"
    }
}

/// Where time went over a range. `from` and `to` are at most 31 days apart; a longer range
/// is refused with `range_too_long`. `groupBy` is `app`, `title`, `urlHost`, `hour` or
/// `day`; absent means `app`.
// MARK: - TPCapturedSummaryInput
struct TPCapturedSummaryInput: Codable, Equatable, Sendable {
    let from: String
    let groupBy: TPSummaryGrouping?
    let to: String

    enum CodingKeys: String, CodingKey {
        case from = "from"
        case groupBy = "groupBy"
        case to = "to"
    }
}

enum TPSummaryGrouping: String, Codable, Equatable, Sendable {
    case app = "app"
    case day = "day"
    case hour = "hour"
    case title = "title"
    case urlHost = "urlHost"
}

/// The range totalled: `activeSeconds` of activity, `paused` per reason, `groups` in the
/// grouping asked for, `switches` between them, the `longestFocus` stretch and `counts` of
/// each kind of item. `groups` is at most 25 for an agent and 744 for the interface, which
/// is every hour of 31 days.
// MARK: - TPCapturedSummaryOutput
struct TPCapturedSummaryOutput: Codable, Equatable, Sendable {
    let activeSeconds: Int
    let counts: TPSummaryCounts
    let groups: [TPSummaryGroup]
    let longestFocus: TPLongestFocus?
    let notice: TPCapturedNotice
    let ok: Bool
    let paused: [TPSummaryPause]
    let switches: Int
    let truncated: Bool?

    enum CodingKeys: String, CodingKey {
        case activeSeconds = "activeSeconds"
        case counts = "counts"
        case groups = "groups"
        case longestFocus = "longestFocus"
        case notice = "notice"
        case ok = "ok"
        case paused = "paused"
        case switches = "switches"
        case truncated = "truncated"
    }
}

