/// Draw on the screen, over the display the shot came from. `on` is a `shot:` id. `marks` is
/// 1 to 40 marks, all refused together if any one of them is wrong. `layer` names the group
/// they join and absent means `default`; `replace` absent means false, so marks are added to
/// the layer rather than replacing it.
// MARK: - TPScreenDrawInput
struct TPScreenDrawInput: Codable, Equatable, Sendable {
    let layer: String?
    let marks: [TPDrawMark]
    /// The shot to draw on: an id beginning `shot:`, from `screen_capture`. A watcher frame or a
    /// bundle frame has a different geometry and is refused.
    let on: String
    let replace: Bool?

    enum CodingKeys: String, CodingKey {
        case layer = "layer"
        case marks = "marks"
        case on = "on"
        case replace = "replace"
    }
}

/// One mark to draw, in the pixels of the shot it is drawn on, origin top-left. `box`,
/// `kind`, `color` and `stroke` are always given, and `n` is filled in for you. The kind
/// decides the rest, and a mark that is missing its kind's fields is refused: `line` and
/// `arrow` require `from` and `to`; `pen` and `highlight` require `points`; `badge` requires
/// `center` and `label`; `text` requires `origin`.
// MARK: - TPDrawMark
struct TPDrawMark: Codable, Equatable, Sendable {
    let box: [Int]
    let center: [Int]?
    let color: TPMarkColor
    let from: [Int]?
    let kind: TPMarkKind
    let label: Int?
    let n: Int?
    let note: String?
    let origin: [Int]?
    let points: [[Int]]?
    let stroke: Int
    let to: [Int]?
    let underText: String?

    enum CodingKeys: String, CodingKey {
        case box = "box"
        case center = "center"
        case color = "color"
        case from = "from"
        case kind = "kind"
        case label = "label"
        case n = "n"
        case note = "note"
        case origin = "origin"
        case points = "points"
        case stroke = "stroke"
        case to = "to"
        case underText = "underText"
    }
}

